/**
 * Book cover rendering on a canvas: editable layout templates (honest, deterministic designs —
 * not AI images), optional background art (an uploaded image or one generated by the image
 * model when configured), eBook covers and full paperback wraps with spine and bleed.
 */
import { SANS, SERIF } from "./fonts";

export type TemplateId = "classic" | "bold" | "minimal" | "photo" | "gradient" | "noir" | "soft" | "playful" | "nonfiction" | "stars";
export const TEMPLATES: { id: TemplateId; name: string; suits: string }[] = [
  { id: "classic", name: "Classic frame", suits: "Literary fiction, memoir, history" },
  { id: "bold", name: "Bold type", suits: "Business, self-help, thrillers" },
  { id: "minimal", name: "Minimal", suits: "Essays, poetry, design, modern non-fiction" },
  { id: "photo", name: "Full image", suits: "Any genre with strong artwork or a photo" },
  { id: "gradient", name: "Gradient glow", suits: "Tech, personal growth, sci-fi" },
  { id: "noir", name: "Noir", suits: "Thriller, crime, horror" },
  { id: "soft", name: "Soft arch", suits: "Romance, women's fiction, faith & inspiration" },
  { id: "playful", name: "Playful shapes", suits: "Children's and young readers" },
  { id: "nonfiction", name: "Promise band", suits: "How-to, business, health" },
  { id: "stars", name: "Night sky", suits: "Fantasy, sci-fi, spiritual" },
];

export interface Palette { bg: string; bg2: string; fg: string; accent: string }
export interface CoverDesign {
  template: TemplateId;
  palette: Palette;
  titleFont: "serif" | "sans";
  titleScale: number; // 0.7–1.4
  align: "center" | "left";
  uppercase: boolean;
  overlay: number; // 0–0.9, darkening over background art
  seed: number;
  imageFocus: number; // 0–1 vertical focus of background art
}
export interface CoverText { title: string; subtitle?: string; author: string; tagline?: string; series?: string; blurb?: string; bio?: string }

export const PALETTES: Record<string, Palette> = {
  midnight: { bg: "#0b0d24", bg2: "#2b1f6b", fg: "#ffffff", accent: "#f5b544" },
  ember: { bg: "#3b0d0d", bg2: "#a3261b", fg: "#fff3e6", accent: "#ffb347" },
  ocean: { bg: "#0d3b4a", bg2: "#0d6b6e", fg: "#ffffff", accent: "#e6a65d" },
  forest: { bg: "#13261b", bg2: "#2e5a3c", fg: "#f3f0e6", accent: "#d9b45a" },
  blush: { bg: "#f7e1e3", bg2: "#e8a5b5", fg: "#3d1730", accent: "#a8325e" },
  sun: { bg: "#ffb347", bg2: "#ff6a3d", fg: "#1d1033", accent: "#1d1033" },
  paper: { bg: "#f4efe6", bg2: "#e2d6c3", fg: "#1f1d1a", accent: "#b23a2a" },
  ink: { bg: "#0a0a12", bg2: "#3a0d12", fg: "#ffe6e6", accent: "#e3342f" },
  mint: { bg: "#e5f6ef", bg2: "#9fdcc4", fg: "#103326", accent: "#ff6b6b" },
  violet: { bg: "#1d1033", bg2: "#6d5bff", fg: "#ffffff", accent: "#3dd6f5" },
};

export const DEFAULT_DESIGN: CoverDesign = { template: "classic", palette: PALETTES.midnight, titleFont: "serif", titleScale: 1, align: "center", uppercase: false, overlay: 0.35, seed: 7, imageFocus: 0.5 };

/** Genre → template/palette suggestions used when AI concepts aren't available. Clearly labelled as template suggestions. */
export function suggestConcepts(genre: string, style: string, seed = 1): (CoverDesign & { name: string; why: string })[] {
  const g = `${genre} ${style}`.toLowerCase();
  const pick = (ids: [TemplateId, keyof typeof PALETTES, "serif" | "sans", string][]) => ids.map(([t, p, f, why], i) => ({ ...DEFAULT_DESIGN, template: t, palette: PALETTES[p], titleFont: f, uppercase: t === "bold" || t === "noir", align: t === "minimal" || t === "nonfiction" ? "left" as const : "center" as const, seed: seed * 13 + i * 7, name: TEMPLATES.find((x) => x.id === t)!.name, why }));
  if (/thrill|crime|mystery|horror|suspense/.test(g)) return pick([["noir", "ink", "serif", "High contrast and a single red accent read as suspense at thumbnail size."], ["bold", "midnight", "sans", "Big, tight capitals are common on bestselling thrillers' covers."], ["photo", "ink", "serif", "Room for a moody photo with a dark overlay keeping the title legible."], ["gradient", "ember", "sans", "Warm-to-dark gradient for tension without imagery."]]);
  if (/romance|love|women|faith|inspir|devotion/.test(g)) return pick([["soft", "blush", "serif", "Soft colours and an arch frame signal warmth and romance."], ["classic", "paper", "serif", "Elegant serif type and a fine frame for a timeless feel."], ["photo", "blush", "serif", "Space for a couple or landscape photo with a light overlay."], ["minimal", "mint", "serif", "Fresh, calm and modern."]]);
  if (/child|kid|young|picture|ya\b|teen/.test(g)) return pick([["playful", "sun", "sans", "Bright shapes and rounded type for young readers."], ["playful", "mint", "sans", "Softer palette for bedtime and early readers."], ["photo", "sun", "sans", "Use an illustration as the background."], ["stars", "violet", "sans", "Adventure and wonder."]]);
  if (/fantasy|sci|space|magic|spirit|myth/.test(g)) return pick([["stars", "violet", "serif", "A starfield and glow suggest other worlds."], ["stars", "midnight", "serif", "Darker, epic variant."], ["photo", "midnight", "serif", "For painted fantasy artwork."], ["gradient", "violet", "sans", "Clean sci-fi look."]]);
  if (/business|self|how|guide|money|health|market|lead|growth|non/.test(g)) return pick([["nonfiction", "violet", "sans", "A coloured band carries the book's promise; author name is prominent."], ["bold", "sun", "sans", "Large title words fill the cover and stay readable as a thumbnail."], ["minimal", "paper", "sans", "Understated and confident for professional readers."], ["gradient", "ocean", "sans", "Modern and calm."]]);
  return pick([["classic", "ocean", "serif", "A fine frame and serif type suit literary and general fiction."], ["photo", "midnight", "serif", "Full-bleed art with a gentle overlay."], ["minimal", "paper", "serif", "Typographic and modern."], ["gradient", "ember", "sans", "Warm and contemporary."]]);
}

function rng(seed: number) { let s = seed >>> 0 || 1; return () => { s ^= s << 13; s ^= s >>> 17; s ^= s << 5; return ((s >>> 0) % 100000) / 100000; }; }
const font = (d: CoverDesign, weight: number, px: number, italic = false, forceSans = false) => `${italic ? "italic " : ""}${weight} ${Math.round(px)}px ${forceSans || d.titleFont === "sans" ? `${SANS}, Arial, sans-serif` : `${SERIF}, Georgia, serif`}`;

type Ctx = CanvasRenderingContext2D;

/** Wrap text into lines that fit `maxW`; shrinks the size until at most `maxLines` lines fit. */
export function fitText(ctx: Ctx, text: string, fontFor: (px: number) => string, maxW: number, startPx: number, maxLines: number, minPx = 10): { px: number; lines: string[] } {
  let px = startPx;
  const words = text.trim().split(/\s+/).filter(Boolean);
  for (; px >= minPx; px *= 0.94) {
    ctx.font = fontFor(px);
    const lines: string[] = []; let cur = "";
    let tooWide = false;
    for (const w of words) {
      const t = cur ? `${cur} ${w}` : w;
      if (ctx.measureText(t).width <= maxW) cur = t;
      else { if (cur) lines.push(cur); cur = w; if (ctx.measureText(w).width > maxW) tooWide = true; }
    }
    if (cur) lines.push(cur);
    if (lines.length <= maxLines && !tooWide) return { px, lines };
  }
  ctx.font = fontFor(minPx);
  return { px: minPx, lines: [text] };
}

function drawLines(ctx: Ctx, lines: string[], x: number, y: number, lh: number, align: CanvasTextAlign) {
  ctx.textAlign = align;
  lines.forEach((l, i) => ctx.fillText(l, x, y + i * lh));
  return y + lines.length * lh;
}

/**
 * Draw the front cover into the rectangle (x, y, w, h) — the trim area. `bleed` extra pixels
 * around it are painted with background so the edges can be trimmed.
 */
export function drawFront(ctx: Ctx, r: { x: number; y: number; w: number; h: number; bleed?: number }, d: CoverDesign, t: CoverText, art?: CanvasImageSource & { width: number; height: number } | null) {
  const { x, y, w, h } = r; const b = r.bleed ?? 0;
  const P = d.palette; const R = rng(d.seed);
  const tt = d.uppercase ? t.title.toUpperCase() : t.title;
  ctx.save();
  ctx.beginPath(); ctx.rect(x - b, y - b, w + 2 * b, h + 2 * b); ctx.clip();
  const bgGrad = (a: string, c: string, angle = 0) => { const g = ctx.createLinearGradient(x, y + (angle ? 0 : 0), x + (angle ? w : 0), y + h); g.addColorStop(0, a); g.addColorStop(1, c); return g; };
  const safe = Math.min(w, h) * 0.075; // text kept well inside the trim (≥ 0.125 in at print sizes)
  const cx = d.align === "center" ? x + w / 2 : x + safe * 1.4;
  const tAlign: CanvasTextAlign = d.align === "center" ? "center" : "left";
  const maxW = w - safe * (d.align === "center" ? 2.4 : 2.8);
  const titleFont = (px: number) => font(d, d.titleFont === "sans" ? 800 : 700, px);
  const S = d.titleScale;

  const paintArt = (overlay: number) => {
    if (art && art.width > 0) {
      const k = Math.max((w + 2 * b) / art.width, (h + 2 * b) / art.height);
      const aw = art.width * k, ah = art.height * k;
      ctx.drawImage(art, x - b + (w + 2 * b - aw) / 2, y - b + (h + 2 * b - ah) * d.imageFocus, aw, ah);
      const g = ctx.createLinearGradient(x, y, x, y + h);
      g.addColorStop(0, `rgba(0,0,0,${overlay * 0.6})`); g.addColorStop(0.55, `rgba(0,0,0,${overlay * 0.25})`); g.addColorStop(1, `rgba(0,0,0,${Math.min(0.95, overlay * 1.4)})`);
      ctx.fillStyle = g; ctx.fillRect(x - b, y - b, w + 2 * b, h + 2 * b);
      return true;
    }
    return false;
  };

  ctx.fillStyle = bgGrad(P.bg, P.bg2); ctx.fillRect(x - b, y - b, w + 2 * b, h + 2 * b);
  ctx.textBaseline = "alphabetic";

  switch (d.template) {
    case "classic": {
      ctx.fillStyle = P.bg; ctx.fillRect(x - b, y - b, w + 2 * b, h + 2 * b);
      if (paintArt(d.overlay)) { /* art behind the frame */ }
      ctx.strokeStyle = P.accent; ctx.lineWidth = Math.max(2, w * 0.006);
      const m = safe * 0.9; ctx.strokeRect(x + m, y + m, w - 2 * m, h - 2 * m);
      ctx.lineWidth = Math.max(1, w * 0.002); ctx.strokeRect(x + m * 1.35, y + m * 1.35, w - 2.7 * m, h - 2.7 * m);
      ctx.fillStyle = P.fg;
      const f = fitText(ctx, tt, titleFont, w * 0.72, w * 0.13 * S, 4);
      ctx.font = titleFont(f.px);
      let yy = drawLines(ctx, f.lines, x + w / 2, y + h * 0.36, f.px * 1.12, "center");
      ctx.fillStyle = P.accent; ctx.fillRect(x + w / 2 - w * 0.08, yy - f.px * 0.35, w * 0.16, Math.max(2, w * 0.004));
      if (t.subtitle) { const s = fitText(ctx, t.subtitle, (px) => font(d, 400, px, true), w * 0.66, w * 0.045, 3); ctx.fillStyle = P.fg; ctx.font = font(d, 400, s.px, true); drawLines(ctx, s.lines, x + w / 2, yy + s.px * 1.4, s.px * 1.3, "center"); }
      ctx.fillStyle = P.fg; const a = fitText(ctx, t.author.toUpperCase(), (px) => font(d, 400, px, false, true), w * 0.7, w * 0.045, 1); ctx.font = font(d, 400, a.px, false, true);
      ctx.letterSpacing = `${Math.round(a.px * 0.18)}px`; ctx.textAlign = "center"; ctx.fillText(a.lines[0], x + w / 2, y + h - safe * 2.6); ctx.letterSpacing = "0px";
      break;
    }
    case "bold": {
      if (!paintArt(d.overlay * 0.8)) { ctx.fillStyle = P.bg; ctx.fillRect(x - b, y - b, w + 2 * b, h + 2 * b); ctx.fillStyle = P.bg2; ctx.fillRect(x - b, y + h * 0.62, w + 2 * b, h * 0.38 + b); }
      ctx.fillStyle = P.fg;
      const f = fitText(ctx, tt, (px) => font({ ...d, titleFont: "sans" }, 800, px), maxW, w * 0.2 * S, 5);
      ctx.font = font({ ...d, titleFont: "sans" }, 800, f.px);
      drawLines(ctx, f.lines, cx, y + safe * 2 + f.px, f.px * 0.98, tAlign);
      if (t.subtitle) { const s = fitText(ctx, t.subtitle, (px) => font(d, 400, px, false, true), maxW, w * 0.045, 3); ctx.font = font(d, 400, s.px, false, true); ctx.fillStyle = P.accent; drawLines(ctx, s.lines, cx, y + h * 0.66 + s.px, s.px * 1.3, tAlign); }
      ctx.fillStyle = P.fg; const a = fitText(ctx, t.author.toUpperCase(), (px) => font(d, 700, px, false, true), maxW, w * 0.06, 1); ctx.font = font(d, 700, a.px, false, true); ctx.textAlign = tAlign; ctx.fillText(a.lines[0], cx, y + h - safe * 1.6);
      break;
    }
    case "minimal": {
      ctx.fillStyle = P.bg; ctx.fillRect(x - b, y - b, w + 2 * b, h + 2 * b);
      paintArt(d.overlay * 0.5);
      ctx.fillStyle = P.accent; ctx.fillRect(x + safe * 1.4, y + safe * 1.6, w * 0.12, Math.max(3, w * 0.008));
      ctx.fillStyle = P.fg;
      const f = fitText(ctx, tt, titleFont, maxW, w * 0.1 * S, 5);
      ctx.font = titleFont(f.px);
      const yy = drawLines(ctx, f.lines, x + safe * 1.4, y + safe * 2.2 + f.px, f.px * 1.1, "left");
      if (t.subtitle) { const s = fitText(ctx, t.subtitle, (px) => font(d, 400, px, true), maxW, w * 0.04, 3); ctx.font = font(d, 400, s.px, true); drawLines(ctx, s.lines, x + safe * 1.4, yy + s.px * 0.8, s.px * 1.3, "left"); }
      const a = fitText(ctx, t.author, (px) => font(d, 400, px, false, true), maxW, w * 0.045, 1); ctx.font = font(d, 400, a.px, false, true); ctx.textAlign = "left"; ctx.fillText(a.lines[0], x + safe * 1.4, y + h - safe * 1.6);
      break;
    }
    case "photo": {
      if (!paintArt(d.overlay)) {
        // no image yet: an abstract placeholder made from the palette (labelled in the UI)
        for (let i = 0; i < 6; i++) { ctx.fillStyle = `${i % 2 ? P.bg2 : P.accent}33`; ctx.beginPath(); ctx.arc(x + R() * w, y + R() * h * 0.7, w * (0.2 + R() * 0.4), 0, Math.PI * 2); ctx.fill(); }
        const g = ctx.createLinearGradient(x, y + h * 0.4, x, y + h); g.addColorStop(0, "rgba(0,0,0,0)"); g.addColorStop(1, "rgba(0,0,0,.6)"); ctx.fillStyle = g; ctx.fillRect(x - b, y - b, w + 2 * b, h + 2 * b);
      }
      ctx.fillStyle = P.fg;
      const f = fitText(ctx, tt, titleFont, maxW, w * 0.13 * S, 4);
      ctx.font = titleFont(f.px);
      const top = y + h * 0.62;
      ctx.shadowColor = "rgba(0,0,0,.45)"; ctx.shadowBlur = w * 0.02;
      const yy = drawLines(ctx, f.lines, cx, top, f.px * 1.08, tAlign);
      if (t.subtitle) { const s = fitText(ctx, t.subtitle, (px) => font(d, 400, px, true), maxW, w * 0.042, 2); ctx.font = font(d, 400, s.px, true); drawLines(ctx, s.lines, cx, yy + s.px * 0.4, s.px * 1.3, tAlign); }
      const a = fitText(ctx, t.author.toUpperCase(), (px) => font(d, 600, px, false, true), maxW, w * 0.048, 1); ctx.font = font(d, 600, a.px, false, true); ctx.textAlign = tAlign; ctx.fillText(a.lines[0], cx, y + h - safe * 1.4);
      ctx.shadowBlur = 0;
      if (t.tagline) { const tg = fitText(ctx, t.tagline, (px) => font(d, 400, px, true), maxW, w * 0.036, 2); ctx.font = font(d, 400, tg.px, true); drawLines(ctx, tg.lines, cx, y + safe * 1.8, tg.px * 1.3, tAlign); }
      break;
    }
    case "gradient": {
      const g = ctx.createRadialGradient(x + w * 0.7, y + h * 0.25, w * 0.05, x + w * 0.5, y + h * 0.5, h * 0.8);
      g.addColorStop(0, P.accent); g.addColorStop(0.35, P.bg2); g.addColorStop(1, P.bg);
      ctx.fillStyle = g; ctx.fillRect(x - b, y - b, w + 2 * b, h + 2 * b);
      paintArt(d.overlay * 0.6);
      for (let i = 0; i < 3; i++) { ctx.strokeStyle = `${P.fg}22`; ctx.lineWidth = w * 0.004; ctx.beginPath(); ctx.arc(x + w * 0.7, y + h * 0.25, w * (0.25 + i * 0.16), 0, Math.PI * 2); ctx.stroke(); }
      ctx.fillStyle = P.fg;
      const f = fitText(ctx, tt, titleFont, maxW, w * 0.13 * S, 4);
      ctx.font = titleFont(f.px);
      const yy = drawLines(ctx, f.lines, cx, y + h * 0.56, f.px * 1.06, tAlign);
      if (t.subtitle) { const s = fitText(ctx, t.subtitle, (px) => font(d, 400, px, false, true), maxW, w * 0.04, 3); ctx.font = font(d, 300, s.px, false, true); drawLines(ctx, s.lines, cx, yy + s.px * 0.6, s.px * 1.35, tAlign); }
      const a = fitText(ctx, t.author, (px) => font(d, 700, px, false, true), maxW, w * 0.05, 1); ctx.font = font(d, 700, a.px, false, true); ctx.textAlign = tAlign; ctx.fillText(a.lines[0], cx, y + h - safe * 1.5);
      break;
    }
    case "noir": {
      ctx.fillStyle = P.bg; ctx.fillRect(x - b, y - b, w + 2 * b, h + 2 * b);
      if (!paintArt(Math.max(0.45, d.overlay))) { const g = ctx.createRadialGradient(x + w / 2, y + h * 0.38, 0, x + w / 2, y + h * 0.38, w * 0.8); g.addColorStop(0, P.bg2); g.addColorStop(1, P.bg); ctx.fillStyle = g; ctx.fillRect(x - b, y - b, w + 2 * b, h + 2 * b); }
      ctx.save(); ctx.translate(x + w / 2, y + h * 0.5); ctx.rotate(-0.25); ctx.fillStyle = P.accent; ctx.fillRect(-w, -w * 0.006, 2 * w, w * 0.012); ctx.restore();
      ctx.fillStyle = P.fg;
      const f = fitText(ctx, tt, (px) => font(d, 700, px), w * 0.84, w * 0.14 * S, 4);
      ctx.font = font(d, 700, f.px); ctx.letterSpacing = `${Math.round(f.px * 0.06)}px`;
      ctx.shadowColor = P.accent; ctx.shadowBlur = w * 0.03;
      drawLines(ctx, f.lines, x + w / 2, y + h * 0.3, f.px * 1.05, "center");
      ctx.shadowBlur = 0; ctx.letterSpacing = "0px";
      if (t.tagline) { const tg = fitText(ctx, t.tagline, (px) => font(d, 400, px, true), w * 0.8, w * 0.04, 2); ctx.font = font(d, 400, tg.px, true); drawLines(ctx, tg.lines, x + w / 2, y + h * 0.7, tg.px * 1.3, "center"); }
      else if (t.subtitle) { const s = fitText(ctx, t.subtitle, (px) => font(d, 400, px, true), w * 0.8, w * 0.04, 2); ctx.font = font(d, 400, s.px, true); drawLines(ctx, s.lines, x + w / 2, y + h * 0.7, s.px * 1.3, "center"); }
      const a = fitText(ctx, t.author.toUpperCase(), (px) => font(d, 700, px, false, true), w * 0.8, w * 0.055, 1); ctx.font = font(d, 700, a.px, false, true); ctx.letterSpacing = `${Math.round(a.px * 0.22)}px`; ctx.textAlign = "center"; ctx.fillText(a.lines[0], x + w / 2, y + h - safe * 1.6); ctx.letterSpacing = "0px";
      break;
    }
    case "soft": {
      ctx.fillStyle = P.bg; ctx.fillRect(x - b, y - b, w + 2 * b, h + 2 * b);
      const aw = w * 0.74, ax = x + (w - aw) / 2, at = y + h * 0.12, ab = y + h * 0.7;
      ctx.save(); ctx.beginPath(); ctx.moveTo(ax, ab); ctx.lineTo(ax, at + aw / 2); ctx.arc(ax + aw / 2, at + aw / 2, aw / 2, Math.PI, 0); ctx.lineTo(ax + aw, ab); ctx.closePath(); ctx.clip();
      ctx.fillStyle = P.bg2; ctx.fillRect(ax, at, aw, ab - at);
      if (art) { const k = Math.max(aw / art.width, (ab - at) / art.height); ctx.drawImage(art, ax + (aw - art.width * k) / 2, at + ((ab - at) - art.height * k) * d.imageFocus, art.width * k, art.height * k); }
      else for (let i = 0; i < 9; i++) { ctx.fillStyle = `${P.accent}${i % 2 ? "33" : "22"}`; ctx.beginPath(); ctx.ellipse(ax + R() * aw, at + R() * (ab - at), aw * 0.12, aw * 0.05, R() * 3, 0, Math.PI * 2); ctx.fill(); }
      ctx.restore();
      ctx.fillStyle = P.fg;
      const f = fitText(ctx, tt, (px) => font(d, 700, px, d.titleFont === "serif"), w * 0.84, w * 0.11 * S, 3);
      ctx.font = font(d, 700, f.px, d.titleFont === "serif");
      const yy = drawLines(ctx, f.lines, x + w / 2, ab + f.px * 1.2, f.px * 1.05, "center");
      if (t.subtitle) { const s = fitText(ctx, t.subtitle, (px) => font(d, 400, px, false, true), w * 0.8, w * 0.036, 2); ctx.font = font(d, 400, s.px, false, true); drawLines(ctx, s.lines, x + w / 2, yy + s.px * 0.3, s.px * 1.3, "center"); }
      ctx.fillStyle = P.accent; const a = fitText(ctx, t.author.toUpperCase(), (px) => font(d, 600, px, false, true), w * 0.8, w * 0.042, 1); ctx.font = font(d, 600, a.px, false, true); ctx.letterSpacing = `${Math.round(a.px * 0.2)}px`; ctx.textAlign = "center"; ctx.fillText(a.lines[0], x + w / 2, y + h - safe * 1.3); ctx.letterSpacing = "0px";
      break;
    }
    case "playful": {
      ctx.fillStyle = P.bg; ctx.fillRect(x - b, y - b, w + 2 * b, h + 2 * b);
      paintArt(d.overlay * 0.4);
      const cols = [P.accent, P.bg2, P.fg, "#ffffff"];
      for (let i = 0; i < 14; i++) {
        ctx.fillStyle = `${cols[i % cols.length]}${i % 3 ? "cc" : "88"}`; const px = x + R() * w, py = y + h * 0.45 + R() * h * 0.45, s = w * (0.04 + R() * 0.08);
        ctx.beginPath(); if (i % 3 === 0) ctx.arc(px, py, s, 0, Math.PI * 2); else if (i % 3 === 1) { ctx.moveTo(px, py - s); ctx.lineTo(px + s, py + s); ctx.lineTo(px - s, py + s); ctx.closePath(); } else ctx.rect(px - s, py - s, s * 1.6, s * 1.6); ctx.fill();
      }
      ctx.fillStyle = P.fg;
      const f = fitText(ctx, tt, (px) => font({ ...d, titleFont: "sans" }, 800, px), w * 0.84, w * 0.15 * S, 4);
      ctx.font = font({ ...d, titleFont: "sans" }, 800, f.px); ctx.lineJoin = "round"; ctx.strokeStyle = "#ffffff"; ctx.lineWidth = f.px * 0.12;
      ctx.textAlign = "center"; f.lines.forEach((l, i) => { ctx.strokeText(l, x + w / 2, y + safe * 2 + f.px * (i + 1) * 1.02); ctx.fillText(l, x + w / 2, y + safe * 2 + f.px * (i + 1) * 1.02); });
      const a = fitText(ctx, t.author, (px) => font(d, 700, px, false, true), w * 0.8, w * 0.05, 1); ctx.font = font(d, 700, a.px, false, true); ctx.fillStyle = P.fg; ctx.fillText(a.lines[0], x + w / 2, y + h - safe * 1.4);
      break;
    }
    case "nonfiction": {
      ctx.fillStyle = P.bg; ctx.fillRect(x - b, y - b, w + 2 * b, h + 2 * b);
      paintArt(d.overlay * 0.6);
      ctx.fillStyle = P.bg2; ctx.fillRect(x - b, y + h * 0.08, w + 2 * b, h * 0.14);
      ctx.fillStyle = "#ffffff";
      const promise = t.tagline || t.subtitle || "";
      if (promise) { const p = fitText(ctx, promise.toUpperCase(), (px) => font(d, 700, px, false, true), maxW, w * 0.04, 2); ctx.font = font(d, 700, p.px, false, true); drawLines(ctx, p.lines, x + safe * 1.4, y + h * 0.15 - (p.lines.length - 1) * p.px * 0.6 + p.px * 0.35, p.px * 1.25, "left"); }
      ctx.fillStyle = P.fg;
      const f = fitText(ctx, tt, (px) => font({ ...d, titleFont: "sans" }, 800, px), maxW, w * 0.15 * S, 5);
      ctx.font = font({ ...d, titleFont: "sans" }, 800, f.px);
      const yy = drawLines(ctx, f.lines, x + safe * 1.4, y + h * 0.33 + f.px, f.px * 1.02, "left");
      ctx.fillStyle = P.accent; ctx.fillRect(x + safe * 1.4, yy, w * 0.2, Math.max(4, w * 0.012));
      ctx.fillStyle = P.fg; const a = fitText(ctx, t.author, (px) => font(d, 700, px, false, true), maxW, w * 0.06, 1); ctx.font = font(d, 700, a.px, false, true); ctx.textAlign = "left"; ctx.fillText(a.lines[0], x + safe * 1.4, y + h - safe * 1.5);
      break;
    }
    case "stars": {
      const g = ctx.createLinearGradient(x, y, x, y + h); g.addColorStop(0, P.bg); g.addColorStop(1, P.bg2); ctx.fillStyle = g; ctx.fillRect(x - b, y - b, w + 2 * b, h + 2 * b);
      paintArt(d.overlay);
      for (let i = 0; i < 220; i++) { const s = R() * w * 0.004 + 0.6; ctx.fillStyle = `rgba(255,255,255,${0.3 + R() * 0.7})`; ctx.beginPath(); ctx.arc(x - b + R() * (w + 2 * b), y - b + R() * (h + 2 * b), s, 0, Math.PI * 2); ctx.fill(); }
      const mg = ctx.createRadialGradient(x + w / 2, y + h * 0.42, 0, x + w / 2, y + h * 0.42, w * 0.45); mg.addColorStop(0, `${P.accent}66`); mg.addColorStop(1, `${P.accent}00`); ctx.fillStyle = mg; ctx.fillRect(x, y, w, h);
      ctx.fillStyle = P.fg; ctx.shadowColor = P.accent; ctx.shadowBlur = w * 0.04;
      const f = fitText(ctx, tt, titleFont, w * 0.82, w * 0.13 * S, 4);
      ctx.font = titleFont(f.px);
      const yy = drawLines(ctx, f.lines, x + w / 2, y + h * 0.4, f.px * 1.08, "center");
      ctx.shadowBlur = 0;
      if (t.subtitle) { const s = fitText(ctx, t.subtitle, (px) => font(d, 400, px, true), w * 0.76, w * 0.04, 2); ctx.font = font(d, 400, s.px, true); drawLines(ctx, s.lines, x + w / 2, yy + s.px * 0.5, s.px * 1.3, "center"); }
      const a = fitText(ctx, t.author.toUpperCase(), (px) => font(d, 600, px, false, true), w * 0.8, w * 0.046, 1); ctx.font = font(d, 600, a.px, false, true); ctx.letterSpacing = `${Math.round(a.px * 0.2)}px`; ctx.textAlign = "center"; ctx.fillText(a.lines[0], x + w / 2, y + h - safe * 1.5); ctx.letterSpacing = "0px";
      break;
    }
  }
  if (t.series) { ctx.fillStyle = P.fg; ctx.globalAlpha = 0.85; const sr = fitText(ctx, t.series.toUpperCase(), (px) => font(d, 600, px, false, true), w * 0.7, w * 0.03, 1); ctx.font = font(d, 600, sr.px, false, true); ctx.textAlign = "center"; ctx.fillText(sr.lines[0], x + w / 2, y + safe * 1.3); ctx.globalAlpha = 1; }
  ctx.restore();
}

/** Paperback wrap: back (blurb, bio, barcode area left clear) + spine + front, with bleed. */
export function drawWrap(ctx: Ctx, px: { w: number; h: number; spine: number; bleed: number; trimW: number; trimH: number }, d: CoverDesign, t: CoverText, opts: { spineText: boolean; guides: boolean; dpi: number }, art?: (CanvasImageSource & { width: number; height: number }) | null) {
  const { bleed: b, trimW, trimH, spine } = px;
  const backX = b, spineX = b + trimW, frontX = b + trimW + spine;
  const P = d.palette;
  // background across the whole wrap
  const g = ctx.createLinearGradient(0, 0, px.w, px.h); g.addColorStop(0, P.bg2); g.addColorStop(1, P.bg);
  ctx.fillStyle = g; ctx.fillRect(0, 0, px.w, px.h);
  ctx.fillStyle = P.bg; ctx.fillRect(0, 0, spineX, px.h);
  // front with its background running into the bleed (the left overflow is covered by the spine below)
  ctx.save(); ctx.beginPath(); ctx.rect(frontX, 0, trimW + b, px.h); ctx.clip();
  drawFront(ctx, { x: frontX, y: b, w: trimW, h: trimH, bleed: b }, d, t, art);
  ctx.restore();
  // spine
  ctx.fillStyle = P.bg2; ctx.fillRect(spineX, 0, spine, px.h);
  if (opts.spineText && spine > 0) {
    const pad = 0.0625 * opts.dpi; // keep ≥ 0.0625 in either side of spine text
    const avail = spine - 2 * pad;
    if (avail > 6) {
      ctx.save(); ctx.translate(spineX + spine / 2, b + trimH / 2); ctx.rotate(Math.PI / 2);
      const sz = Math.min(avail * 0.62, trimH * 0.05);
      ctx.fillStyle = P.fg; ctx.textBaseline = "middle"; ctx.textAlign = "left";
      ctx.font = font(d, 700, sz); const tw = Math.min(ctx.measureText(t.title).width, trimH * 0.55);
      ctx.font = font(d, 400, sz * 0.8, false, true); const aw = Math.min(ctx.measureText(t.author).width, trimH * 0.3);
      ctx.font = font(d, 700, sz); ctx.fillText(t.title, -trimH / 2 + trimH * 0.06, 0, trimH * 0.55);
      ctx.font = font(d, 400, sz * 0.8, false, true); ctx.textAlign = "right"; ctx.fillText(t.author, trimH / 2 - trimH * 0.06, 0, trimH * 0.3);
      void tw; void aw;
      ctx.restore();
    }
  }
  // back cover
  const safe = 0.125 * opts.dpi + trimW * 0.06;
  ctx.fillStyle = P.fg; ctx.textBaseline = "alphabetic";
  let y = b + safe + trimW * 0.04;
  if (t.tagline) { const tg = fitText(ctx, t.tagline, (p) => font(d, 700, p), trimW - 2 * safe, trimW * 0.06, 3); ctx.font = font(d, 700, tg.px); y = drawLines(ctx, tg.lines, backX + trimW / 2, y + tg.px, tg.px * 1.2, "center") + tg.px * 0.6; }
  if (t.blurb) {
    const paras = t.blurb.split(/\n+/).filter(Boolean);
    const size = trimW * 0.034;
    ctx.font = font(d, 400, size, false, d.titleFont === "sans");
    ctx.textAlign = "left";
    for (const p of paras) {
      const words = p.split(/\s+/); let line = "";
      for (const w of words) { const tt = line ? `${line} ${w}` : w; if (ctx.measureText(tt).width > trimW - 2 * safe) { ctx.fillText(line, backX + safe, y); y += size * 1.45; line = w; } else line = tt; if (y > b + trimH * 0.66) break; }
      if (line && y <= b + trimH * 0.66) { ctx.fillText(line, backX + safe, y); y += size * 1.45; }
      y += size * 0.6;
      if (y > b + trimH * 0.66) break;
    }
  }
  if (t.bio) { const s = trimW * 0.028; ctx.font = font(d, 400, s, true); const f = fitText(ctx, t.bio, (p) => font(d, 400, p, true), trimW - 2 * safe, s, 5, s * 0.8); ctx.font = font(d, 400, f.px, true); drawLines(ctx, f.lines, backX + safe, Math.max(y + s, b + trimH * 0.7), f.px * 1.35, "left"); }
  // barcode area kept clear (lower right of the back cover), labelled only in guides
  const bw = 2 * opts.dpi, bh = 1.2 * opts.dpi;
  const bx = spineX - safe - bw, by = b + trimH - safe - bh;
  if (opts.guides) {
    ctx.save(); ctx.setLineDash([opts.dpi * 0.04, opts.dpi * 0.04]);
    ctx.strokeStyle = "rgba(255,0,0,.85)"; ctx.lineWidth = Math.max(2, opts.dpi * 0.006);
    ctx.strokeRect(b, b, px.w - 2 * b, px.h - 2 * b); // trim
    ctx.strokeStyle = "rgba(0,160,255,.9)"; ctx.strokeRect(spineX, 0, spine, px.h); // spine
    ctx.strokeStyle = "rgba(0,200,120,.9)"; const sf = 0.125 * opts.dpi; ctx.strokeRect(b + sf, b + sf, trimW - 2 * sf, trimH - 2 * sf); ctx.strokeRect(frontX + sf, b + sf, trimW - 2 * sf, trimH - 2 * sf);
    ctx.strokeStyle = "rgba(255,255,255,.9)"; ctx.strokeRect(bx, by, bw, bh);
    ctx.fillStyle = "rgba(255,255,255,.9)"; ctx.font = `${Math.round(opts.dpi * 0.09)}px ${SANS}, sans-serif`; ctx.textAlign = "center"; ctx.fillText("Barcode area (check KDP template)", bx + bw / 2, by + bh / 2);
    ctx.restore();
  }
}

/** Load an image (data URL or same-origin URL) into an ImageBitmap-like element. */
export function loadImage(src: string): Promise<HTMLImageElement> {
  return new Promise((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = () => rej(new Error("The image couldn't be read.")); i.src = src; });
}

export function canvasBlob(c: HTMLCanvasElement, type: "image/jpeg" | "image/png", q = 0.92): Promise<Blob> {
  return new Promise((res, rej) => c.toBlob((b) => (b ? res(b) : rej(new Error("The image couldn't be created (the browser ran out of memory?)."))), type, q));
}
